import React, { useState } from 'react';
import './App.css';
import Navbar from './Navbar';
import ProductCard from './ProductCard';

function App() {
  const [cart, setCart] = useState([]);
  const [isCartOpen, setIsCartOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  const products = [
    { id: 1, name: 'Whisper Ultra Softs Air Fresh Pads', price: 379, image: 'https://images.unsplash.com/photo-1550572017-edd951b55104?w=500' },
    { id: 2, name: 'Stayfree Advanced All Nights Pads', price: 264, image: 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=500' },
    { id: 3, name: 'Azah Rash-Free Organic Cotton Pads', price: 270, image: 'https://images.unsplash.com/photo-1631549916768-4119b255f9ed?w=500' },
    { id: 4, name: 'Niine Naturally Soft Day & Night Pads', price: 223, image: 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?w=500' }
  ];

  const addToCart = (product) => {
    setCart((prevCart) => {
      const existingProduct = prevCart.find(item => item.id === product.id);
      if (existingProduct) {
        return prevCart.map(item =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prevCart, { ...product, quantity: 1 }];
    });
  };

  const removeFromCart = (productId) => {
    setCart((prevCart) => prevCart.filter(item => item.id !== productId));
  };

  const filteredProducts = products.filter(product =>
    product.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const totalCartItems = cart.reduce((total, item) => total + item.quantity, 0);
  const totalPrice = cart.reduce((total, item) => total + (item.price * item.quantity), 0);

  return (
    <div className="app-container">
      <Navbar cartCount={totalCartItems} onCartClick={() => setIsCartOpen(!isCartOpen)} />

      <header className="hero-section">
        <h1>Sunanda Pages</h1>
        <p>Your Premium Personal Care & Hygiene Essentials Store</p>

        <div className="search-container">
          <input 
            type="text" 
            placeholder="Search products (e.g., Whisper, Stayfree, Organic)..." 
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="search-bar"
          />
        </div>
      </header>

      <main className="main-content">
        <h2 className="section-title">Shop Personal Care Essentials</h2>

        {filteredProducts.length === 0 ? (
          <p className="no-results">No products match your search query.</p>
        ) : (
          <div className="product-grid">
            {filteredProducts.map(product => (
              <ProductCard key={product.id} product={product} onAddToCart={addToCart} />
            ))}
          </div>
        )}

        {isCartOpen && (
          <div className="cart-overlay">
            <div className="cart-modal">
              <h2>Your Shopping Cart</h2>
              <button className="close-btn" onClick={() => setIsCartOpen(false)}>×</button>

              {cart.length === 0 ? (
                <p className="empty-message">Your cart is feeling a bit light!</p>
              ) : (
                <>
                  <div className="cart-items-list">
                    {cart.map(item => (
                      <div key={item.id} className="cart-item">
                        <div>
                          <h4>{item.name}</h4>
                          <p>₹{item.price} x {item.quantity}</p>
                        </div>
                        <button className="remove-btn" onClick={() => removeFromCart(item.id)}>Remove</button>
                      </div>
                    ))}
                  </div>
                  <div className="cart-summary">
                    <h3>Total: ₹{totalPrice}</h3>
                    <button className="checkout-btn" onClick={() => alert('Proceeding to checkout!')}>Checkout Now</button>
                  </div>
                </>
              )}
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
